// 2. Code: Normalize Event — parse payload and validate lead/request IDs
const item = $input.first().json;
let payload = {};

if (item.content) {
  try {
    payload = typeof item.content === 'string' ? JSON.parse(item.content) : item.content;
  } catch (err) {
    payload = {};
  }
} else {
  payload = item;
}

// Support wrapped event ({ data: { ... } }) and flat event
const eventData = payload.data || payload;
const leadId = eventData.leadId || payload.leadId || null;
const workflowRunId = eventData.workflowRunId || payload.workflowRunId || null;
const provider = (eventData.provider || payload.provider || 'MOCK').toUpperCase();

if (!leadId) {
  throw new Error('Validation error: Missing leadId in RabbitMQ payload');
}

return [{
  json: {
    leadId,
    workflowRunId,
    provider,
    rawEvent: payload
  }
}];

// 4. Code: Extract Domain — normalize email and website; identify free-email domains
const leadResponse = $input.first().json;
const eventMeta = $('Code: Normalize Event').first().json;

// Extract authoritative lead fields or fallback to event payload
const lead = leadResponse.id ? leadResponse : (eventMeta.rawEvent?.data || eventMeta.rawEvent || {});
const leadId = eventMeta.leadId;
const workflowRunId = eventMeta.workflowRunId;
const provider = eventMeta.provider || 'MOCK';

const rawEmail = (lead.email || '').trim().toLowerCase();
const rawWebsite = (lead.companyWebsite || lead.website || '').trim();
const companyName = lead.companyName || '';

let emailDomain = '';
if (rawEmail.includes('@')) {
  emailDomain = rawEmail.split('@')[1].trim().toLowerCase();
}

const freeEmailProviders = new Set([
  'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com', 'icloud.com', 'mail.com', 'aol.com'
]);
const isFreeEmail = freeEmailProviders.has(emailDomain);

let normalizedDomain = '';
let cleanWebsiteUrl = '';

if (rawWebsite) {
  normalizedDomain = rawWebsite
    .replace(/^(?:https?:\/\/)?(?:www\.)?/i, '')
    .split('/')[0]
    .split('?')[0]
    .split('#')[0]
    .split(':')[0]
    .trim()
    .toLowerCase();
  cleanWebsiteUrl = `https://${normalizedDomain}`;
} else if (!isFreeEmail && emailDomain) {
  normalizedDomain = emailDomain;
  cleanWebsiteUrl = `https://${emailDomain}`;
}

if (!normalizedDomain) {
  if (companyName) {
    const slug = companyName.toLowerCase().replace(/[^a-z0-9]/g, '');
    normalizedDomain = slug ? `${slug}.com` : 'enterprise.com';
  } else {
    normalizedDomain = 'enterprise.com';
  }
}

return [{
  json: {
    leadId,
    workflowRunId,
    provider,
    email: rawEmail,
    emailDomain,
    isFreeEmail,
    domain: normalizedDomain,
    website: cleanWebsiteUrl,
    companyName,
    lead
  }
}];

// 6. Code: Normalize Provider Result — map provider fields into the agreed schema
const response = $input.first().json;
const prep = $('Code: Extract Domain').first().json;

const company = response.company || {};
const contact = response.contact || {};

const companyName = company.name || response.companyName || prep.companyName || null;
const companyWebsite = company.website || response.companyWebsite || prep.website || (prep.domain ? `https://${prep.domain}` : null);
const industry = company.industry || response.industry || response.companyIndustry || null;

let companySize = null;
if (typeof company.size === 'number') {
  companySize = company.size;
} else if (typeof response.companySize === 'number') {
  companySize = response.companySize;
} else if (typeof company.size === 'string') {
  const match = company.size.match(/\d+/);
  companySize = match ? parseInt(match[0], 10) : null;
}

const jobTitle = contact.jobTitle || response.jobTitle || response.contactJobTitle || null;
const linkedInUrl = contact.linkedinUrl || response.linkedInUrl || response.contactLinkedinUrl || null;

return [{
  json: {
    leadId: prep.leadId,
    workflowRunId: prep.workflowRunId,
    provider: 'MOCK',
    companyName,
    companyWebsite,
    industry,
    companySize,
    jobTitle,
    linkedInUrl,
    rawResponse: response.rawResponse || response,
    httpStatus: response.statusCode || 200
  }
}];

// 7. Code: Validate Completeness — distinguish SUCCESS, PARTIAL, and FAILED; never manufacture unknown data
const item = $input.first().json;

const hasCritical = Boolean(item.companyName && (item.industry || item.companySize));
const hasAny = Boolean(item.companyName || item.industry || item.companySize || item.jobTitle);

let status = 'FAILED';
let errorMessage = null;

if (hasCritical && item.jobTitle) {
  status = 'SUCCESS';
} else if (hasAny) {
  status = 'PARTIAL';
  errorMessage = 'Partial firmographics enrichment: missing some company or contact attributes';
} else {
  status = 'FAILED';
  errorMessage = 'Enrichment provider returned no usable firmographics data';
}

return [{
  json: {
    leadId: item.leadId,
    workflowRunId: item.workflowRunId,
    status,
    provider: 'MOCK',
    companyName: item.companyName,
    companyWebsite: item.companyWebsite,
    industry: item.industry,
    companySize: item.companySize,
    jobTitle: item.jobTitle,
    linkedInUrl: item.linkedInUrl,
    rawResponse: item.rawResponse,
    errorMessage
  }
}];

