// 11. Code: Build Run Summary — include provider mode (real/mock), status and correlation IDs
const val = $('Code: Validate Completeness').first().json;

return [{
  json: {
    leadId: val.leadId,
    workflowRunId: val.workflowRunId,
    status: val.status,
    providerMode: 'MOCK',
    provider: val.provider,
    companyName: val.companyName,
    industry: val.industry,
    companySize: val.companySize,
    hasCriticalFields: Boolean(val.companyName && val.industry),
    errorMessage: val.errorMessage || null,
    completedAt: new Date().toISOString()
  }
}];

// 12. Code: Finalize Execution Output — return a final structured output for n8n execution/logging
const summary = $input.first().json;

return [{
  json: {
    success: summary.status === 'SUCCESS' || summary.status === 'PARTIAL',
    leadId: summary.leadId,
    workflowRunId: summary.workflowRunId,
    status: summary.status,
    providerMode: summary.providerMode,
    summary: `[Enrichment ${summary.status}] Company: ${summary.companyName || 'N/A'}, Size: ${summary.companySize || 'N/A'}`,
    audit: {
      executedAt: summary.completedAt,
      workflow: 'T12-WF02',
      agent: 'AI Lead Enrichment Agent'
    }
  }
}];
